package com.autoops.execution.executor;import com.autoops.infrastructure.remote.RemoteClient;import com.autoops.workflow.entity.CommandStep;import org.springframework.stereotype.Component;@Component public class CommandStepExecutor implements StepExecutor<CommandStep>{private final RemoteClient remote;public CommandStepExecutor(RemoteClient r){remote=r;}public Class<CommandStep> supports(){return CommandStep.class;}public StepResult execute(CommandStep s,ExecutionContext c){var r=remote.execute(c.host(),c.port(),c.username(),c.password(),s.commandForExecution(),s.timeoutSeconds());return new StepResult(r.success(),r.stdout(),r.stderr(),r.exitCode());}}
